(async () => {
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
  const cardOf = (text) => [...document.querySelectorAll('.pj-card')].find((c) => (c.innerText || '').includes(text));
  const out = {};
  const cards = [...document.querySelectorAll('.tb-project-main')];
  out.listTitles = cards.map((c) => (c.innerText || '').split('\n')[0]).join(' | ');
  const target = cards.find((c) => (c.innerText || '').includes('循迹小车')) || cards[0];
  target.click();
  await sleep(3000);
  out.reopened = document.querySelector('.pj-title')?.textContent || null;
  out.descAfterReload = (cardOf('项目描述')?.innerText || '').replace(/\s+/g, ' ').slice(0, 70);
  out.bomTitle = (cardOf('元器件清单')?.querySelector('.pj-card-title')?.textContent || cardOf('元器件清单')?.innerText?.split('\n')[0] || '').trim();
  out.components = (cardOf('项目信息')?.innerText || '').replace(/\s+/g, ' ').match(/使用元器件 [0-9]+ 种/)?.[0] || null;
  const showAll = [...document.querySelectorAll('.pj-link-btn')].find((b) => b.textContent.includes('查看全部'));
  if (showAll) { showAll.click(); await sleep(600); }
  out.bomHasNew = (cardOf('元器件清单')?.innerText || '').includes('持久化测试元件');
  return JSON.stringify(out);
})()
